def decode_ways(s: str) -> int:
    """
    Digits encode letters where 1=A through 26=Z. Return the number of
    possible decodings. A leading zero or invalid zero placement is invalid.
    """
    if not s:
        return 0
    n = len(s)
    if s[0] == '0':
        return 0
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1
    for i in range(2, n + 1):
        if s[i - 1] != '0':
            dp[i] += dp[i - 1]
        two_digit = int(s[i - 2:i])
        if 10 <= two_digit <= 26:
            dp[i] += dp[i - 2]
        if s[i - 1] == '0' and (not (s[i - 2] == '1' or s[i - 2] == '2')):
            return 0
    return dp[n]

