def simplify_path(path: str) -> str:
    """
    Simplify an absolute Unix path. Multiple slashes are equivalent; '.' is
    ignored; '..' moves to the parent unless already at root. Return a path
    beginning with '/'.
    """
    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack)

