def lru_cache_simulation(capacity: int, operations: list) -> list:
    from collections import OrderedDict
    if capacity <= 0:
        return [-1 if op[0] == 'get' else None for op in operations if op[0] == 'get']
    cache = OrderedDict()
    outputs = []
    for op in operations:
        if op[0] == 'get':
            key = op[1]
            if key in cache:
                cache.move_to_end(key)
                outputs.append(cache[key])
            else:
                outputs.append(-1)
        elif op[0] == 'put':
            key, value = (op[1], op[2])
            if key in cache:
                cache[key] = value
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = value
        else:
            continue
    return outputs

