        pref = [0] * (2 * n + 1)
        for i in range(2 * n):
            pref[i + 1] = pref[i] + values[i % n]
        nxt = [0] * (2 * n + 1)
        for i in range(n):
            lo, hi = (i + 1, i + n)
            while lo <= hi:
