def merge_intervals(intervals: list) -> list:
    """
    Merge overlapping closed intervals. Touching intervals such as [1,2]
    and [2,3] also merge. Return intervals sorted by start.
    """
    if not intervals:
        return []
    cleaned = []
    for iv in intervals:
        if len(iv) != 2:
            continue
        start, end = (iv[0], iv[1])
        if start > end:
            start, end = (end, start)
        cleaned.append([start, end])
    cleaned.sort(key=lambda x: x[0])
    merged = []
    for iv in cleaned:
        if not merged:
            merged.append(iv)
        else:
            last = merged[-1]
            if iv[0] <= last[1]:
                last[1] = max(last[1], iv[1])
            else:
                merged.append(iv)
    return merged

