    """
    Group words that are anagrams. Within each group preserve original
    input order. Order groups by the index of their first member.
    """
    groups = {}
    for word in words:
        key = ''.join(sorted(word))
        if key not in groups:
            groups[key] = []
        groups[key].append(word)
    return list(groups.values())

