def minimum_spanning_tree_weight(n: int, edges: list) -> int:
    """
    edges contains undirected [u,v,w] edges with vertices 0..n-1. Return the
    minimum total weight of a spanning tree. The graph is guaranteed connected.
    """
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> bool:
        rx, ry = (find(x), find(y))
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    edges_sorted = sorted(edges, key=lambda e: e[2])
    mst_weight = 0
    edges_used = 0
    for u, v, w in edges_sorted:
        if union(u, v):
            mst_weight += w
            edges_used += 1
            if edges_used == n - 1:
                break
    return mst_weight

