def bipartite_graph(graph: list) -> bool:
    """
    graph[i] lists neighbors of vertex i in an undirected graph.
    Return True if the graph is bipartite.
    """
    n = len(graph)
    color = [-1] * n
    for start in range(n):
        if color[start] != -1:
            continue
        color[start] = 0
        stack = [start]
        while stack:
            v = stack.pop()
            for nb in graph[v]:
                if nb == v:
                    return False
                if color[nb] == -1:
                    color[nb] = 1 - color[v]
                    stack.append(nb)
                elif color[nb] == color[v]:
                    return False
    return True

