def word_ladder_length(begin: str, end: str, words: list) -> int:
    """
    Return the number of words in the shortest transformation sequence from
    begin to end, changing exactly one character at a time. Every intermediate
    word must be in words. Return 0 if impossible. If begin == end, return 1.
    """
    if begin == end:
        return 1
    word_set = set(words)
    if end not in word_set:
        return 0
    from collections import deque
    queue = deque([(begin, 1)])
    visited = {begin}
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    while queue:
        current, length = queue.popleft()
        for i in range(len(current)):
            for c in alphabet:
                if c == current[i]:
                    continue
                next_word = current[:i] + c + current[i + 1:]
                if next_word == end:
                    return length + 1
                if next_word in word_set and next_word not in visited:
                    visited.add(next_word)
                    queue.append((next_word, length + 1))
    return 0

