def minimum_path_sum(grid: list) -> int:
    """
    Return the minimum sum from top-left to bottom-right moving only right or
    down. Grid values are nonnegative.
    """
    if not grid or not grid[0]:
        return 0
    rows, cols = (len(grid), len(grid[0]))
    dp = [0] * cols
    for i in range(rows):
        for j in range(cols):
            if i == 0 and j == 0:
                dp[j] = grid[i][j]
            elif i == 0:
                dp[j] = dp[j - 1] + grid[i][j]
            elif j == 0:
                dp[j] = dp[j] + grid[i][j]
            else:
                dp[j] = min(dp[j], dp[j - 1]) + grid[i][j]
    return dp[-1]

