def jump_game(nums: list) -> bool:
    """
    nums[i] is the maximum jump length from i. Return True if the last index
    is reachable from index 0.
    """
    if not nums:
        return True
    furthest = 0
    for i, jump in enumerate(nums):
        if i > furthest:
            return False
        furthest = max(furthest, i + jump)
        if furthest >= len(nums) - 1:
            return True
    return True

