def circular_queue_simulation(operations: list, capacity: int) -> list:
    """
    Simulate a fixed-capacity FIFO queue. Operations are ('enqueue', x),
    ('dequeue',), and ('front',). Enqueue on a full queue is ignored.
    Dequeue/front on an empty queue append -1. Return outputs from dequeue
    and front operations.
    """
    queue = [None] * capacity
    head = 0
    tail = 0
    size = 0
    outputs = []
    for op in operations:
        if op[0] == 'enqueue':
            x = op[1]
            if size < capacity:
                queue[tail] = x
                tail = (tail + 1) % capacity
                size += 1
        elif op[0] == 'dequeue':
            if size == 0:
                outputs.append(-1)
            else:
                outputs.append(queue[head])
                head = (head + 1) % capacity
                size -= 1
        elif op[0] == 'front':
            if size == 0:
                outputs.append(-1)
            else:
                outputs.append(queue[head])
    return outputs

